INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_92d1ffb31fa379a9ae1d7501","wiki/sources/tnb-inb-2027-data.md",10,"Seite 7","7\n\nRedaktionsstand INB 2027, Arbeitsstand TNB Version 18.1 vom 03.08.2026",10,"{\"canonical_url\":null,\"normalized_sha256\":\"9d0a53bed0c9c73fec9389f24140249ad56832bbbae4e9fa688cbebed542eae9\",\"page\":7,\"source_id\":\"src_a7ec711492a568806e50\",\"source_sha256\":\"27b4073914d75fb2e5667c0017894cae5f062ac402895cac0c3c89054d124a3c\",\"source_version_id\":\"sv_0d113e6fd37611d6bddd8c2f\"}","6f8ee0f2e8dbe307ba4588408294934b546e20a78028166fea15d89373aa506c"],["chunk_0a531c064bf1ecc4321d35ba","wiki/sources/tnb-inb-2027-data.md",11,"Seite 8","Allgemeine Hinweise\n\nAllgemeine Hinweise\n\nDie technischen Netzzugangsbedingungen â€“ kurz: TNB â€“ gelten fÃ¼r den Bereich der Schienenwege der DB InfraGO AG â€“ kurz: dem Netz â€“ und sind Bestandteil der Infrastrukturnutzungsbedingungen der DB InfraGO AG (INB).\n\nDiese TNB geben technikbezogene Anforderungen und Bedingungen bekannt, die fÃ¼r Fahrzeuge im Sinne des Â§ 18 Eisenbahn-Bau- und Betriebsordnung (EBO), die auf dem Netz zum\n\nEinsatz kommen, gelten.\n\nDie Aufteilung der TNB erfolgt in 6 Hauptteile:\n\nTeil A: Zugangsvoraussetzungen\n\nTeil B: Anforderungen an Fahrzeuge\n\nTeil C: Zugbeeinflussungssysteme und Zugfunk\n\nTeil D: Besondere Anforderungen S-Bahn Berlin und S-Bahn Hamburg\n\nTeil E: Neigetechnik, Nebenfahrzeuge, auÃŸergewÃ¶hnliche Fahrzeuge und Transporte\n\nTeil F: Strecken- /Betriebsstellenbezogene Nutzungsvorgaben\n\nDie Anforderungen und mitgeltenden Normen / Richtlinien (Ril) / Verweise gelten generell fÃ¼r\n\nalle Fahrzeuge, die auf dem Netz erstmalig zum Einsatz kommen.\n\nEs ist immer die aktuellste Ausgabe der zitierten Normen / Ril / INB sowie TSI Ìen anzuwenden.\n\nAnforderungen, die aus weitergehenden Auflagen â€“ z. B. des Arbeits- und Umweltschutzes\n\nresultieren, sind nicht Inhalt dieser TNB.\n\nAnfragen zur NetzvertrÃ¤glichkeit sowie besondere Abstimmungen / Vereinbarungen sind zu\n\nrichten an [E-Mail-Adresse entfernt].\n\nDie fÃ¼r die Beantragung der â€žMachbarkeitsstudie/ Zustimmungsantrag fÃ¼r auÃŸergewÃ¶hnliche\n\nTransporteâ€œ und der â€žBefahrbarkeitsprÃ¼fung Ã¼bergroÃŸer Fahrzeugeâ€œ erforderlichen Formulare\n\nkÃ¶nnen im Internet unter www.dbinfrago.com/formulare abgerufen werden.\n\n8\n\nRedaktionsstand INB 2027, Arbeitsstand TNB Version 18.1 vom 03.08.2026",213,"{\"canonical_url\":null,\"normalized_sha256\":\"9d0a53bed0c9c73fec9389f24140249ad56832bbbae4e9fa688cbebed542eae9\",\"page\":8,\"source_id\":\"src_a7ec711492a568806e50\",\"source_sha256\":\"27b4073914d75fb2e5667c0017894cae5f062ac402895cac0c3c89054d124a3c\",\"source_version_id\":\"sv_0d113e6fd37611d6bddd8c2f\"}","52afed40ef6a31c7a1c527c13d1d8475b56715510f4d08a1aaa3e861b5444e57"],["chunk_98aafe9498a54dbef631fdc2","wiki/sources/tnb-inb-2027-data.md",12,"Seite 9","A Zugangsvoraussetzungen\n\nA Zugangsvoraussetzungen\n\nA.1 Allgemein\n\nEin Fahrzeug kann im Netz zum Einsatz kommen, wenn es Ã¼ber eine â€žAbnahme eines Fahrzeugs nach Â§ 32 Eisenbahn-Bau- und Betriebsordnung (EBO)â€œ und/oder eine â€žGenehmigung\n\nfÃ¼r das Inverkehrbringen eines Fahrzeugs nach Â§ 9 Abs. 1 oder Abs. 3 der Verordnung Ã¼ber\n\ndie Erteilung von Inbetriebnahmegenehmigungen fÃ¼r das Eisenbahnsystem (Eisenbahn-Inbetriebnahmege-nehmigungsverordnung â€“ EIGV)â€œ und/oder Ã¼ber eine â€žInbetriebnahmegenehmigung fÃ¼r ein Fahrzeug nach Â§ 6 Abs. 1 der Verordnung Ã¼ber die InteroperabilitÃ¤t des transeuropÃ¤ischen Eisenbahnsystems (TranseuropÃ¤ische-Eisenbahn-InteroperabilitÃ¤tsverordnung â€“\n\nTEIV [auÃŸer Kraft getreten seit 11.08.2018])â€œ verfÃ¼gt. DarÃ¼ber hinaus hat es den Anforderungen der INB zu entsprechen.\n\nFÃ¼r den konkreten Einsatz zugelassener Fahrzeuge sind die Fahrzeugparameter mit dem Infrastrukturregister (ISR) der DB InfraGO AG abzugleichen.\n\nFahrzeuge mÃ¼ssen sicher, stÃ¶rungs- und fehlerfrei im Netz zum Einsatz kommen.\n\nBesondere Bedin- Fahrzeuge, die den o.g. Zugangsvoraussetzungen nicht folgen, kÃ¶ngungen nen unter Anwendung besonderer Verfahren zum begrenzten Einsatz\n\ngelangen:\n\ndas Verfahren im Zusammenhang mit der Erprobung eines Fahrzeugs\n\nbeschreibt die DB InfraGO AG unter www.dbinfrago.com/probefahrten.\n\ndas Verfahren zur ordnungsgemÃ¤ÃŸen Behandlung eines auÃŸergewÃ¶hnlichen Fahrzeugs ist unter Abschnitt E.4 â€žAuÃŸergewÃ¶hnliche\n\nTransporteâ€œ beschrieben.\n\nSonderbedingun- FÃ¼r Nebenfahrzeuge gelten besondere Bedingungen gemÃ¤ÃŸ Abgen fÃ¼r Neben- schnitt E.2 â€žNebenfahrzeugeâ€œ der TNB. Nach Â§ 18 Abs. 1 EBO braufahrzeuge chen diese den Anforderungen an Regelfahrzeuge nur insoweit zu\n\nentsprechen, als es fÃ¼r den Sonderzweck, dem sie dienen sollen, erforderlich ist.\n\n9",219,"{\"canonical_url\":null,\"normalized_sha256\":\"9d0a53bed0c9c73fec9389f24140249ad56832bbbae4e9fa688cbebed542eae9\",\"page\":9,\"source_id\":\"src_a7ec711492a568806e50\",\"source_sha256\":\"27b4073914d75fb2e5667c0017894cae5f062ac402895cac0c3c89054d124a3c\",\"source_version_id\":\"sv_0d113e6fd37611d6bddd8c2f\"}","9a6831d1f03f5477a854839a0847157fb05bf6f08634585eea73ad4afd8e0ebb"],["chunk_8148b4bdeb5a69d201a44ef9","wiki/sources/tnb-inb-2027-data.md",13,"Seite 9","Redaktionsstand INB 2027, Arbeitsstand TNB Version 18.1 vom 03.08.2026",9,"{\"canonical_url\":null,\"normalized_sha256\":\"9d0a53bed0c9c73fec9389f24140249ad56832bbbae4e9fa688cbebed542eae9\",\"page\":9,\"source_id\":\"src_a7ec711492a568806e50\",\"source_sha256\":\"27b4073914d75fb2e5667c0017894cae5f062ac402895cac0c3c89054d124a3c\",\"source_version_id\":\"sv_0d113e6fd37611d6bddd8c2f\"}","a45036b96377ec595a444e28bfc2f61735c5e34d3d77a2a5d0dbe86a737344c5"],["chunk_a187b52f7e7a3df2e